            while (jarEntries.hasMoreElements()) {
                ZipEntry o1 = (ZipEntry) jarEntries.nextElement();
                if (o1.getName().equalsIgnoreCase("META-INF/MANIFEST.MF") || o1.getSize() <= 0) continue;
